    private String resolveCity(String city) {
        if (city == null) {
            return null;
        }
        String existingCity = this.clinicService.findAllOwners().stream()
            .map(Owner::getCity)
            .filter(existing -> existing != null && existing.equalsIgnoreCase(city))
            .findFirst()
            .orElse(null);
